/*
 * A285985  Numbers a(n) = (T(b(n)))^2, where T(b(n)) is the triangular number
 *          of b(n)= A000217(b(n)) and b(n)=A006451(n). Also a(n) = parameters
 *          K of the Bachet Mordell equation y^2=x^3+K, where x= T(b(n)) =
 *          A006454(n) and y= T(b(n))* sqrt(T(b(n))+1) = A285955(n).
 * https://oeis.org/A285985
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = (T(b(n)))^2 where b(n) is A006451(n), * i.e. numbers n
 *            for which n(n+1)/2 + 1 is a perfect square. * The b-sequence is
 *            generated by the Pell recurrence * m' = 3*m + 8*k , k' = m + 3*k
 *            * with two fundamental solutions (m,k) = (1,1) and (5,2). * From
 *            m we obtain b = (m-1)/2. The algorithm ke...
 * Range:     u8 n <= 2, u16 n <= 3, u32 n <= 6, u64 n <= 12, u128 n <= 25,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>

/* ---- small helper to grow a seq_t array ---- */
static void grow_seq_arr(seq_t **arr, size_t *cap, size_t needed)
{
    if (*cap >= needed) return;
    size_t new_cap = (*cap) ? (*cap) : 4;
    while (new_cap < needed) new_cap <<= 1;
    *arr = (seq_t*)realloc(*arr, new_cap * sizeof(seq_t));
    *cap = new_cap;
}

/* ---- data for the two Pell streams ---- */
typedef struct {
    seq_t m;        /* current term of the Pell equation */
    seq_t k;        /* associated term */
    seq_t next_b;   /* next value of b = (m-1)/2 */
} stream_t;

static stream_t stream[2] = {
    { .m = 1, .k = 1, .next_b = 0 },   /* m=1,k=1 -> b=0   */
    { .m = 5, .k = 2, .next_b = 2 }    /* m=5,k=2 -> b=2   */
};

/* ---- cache for a(n) values ---- */
static seq_t *a_cache      = NULL;
static size_t a_cache_len  = 0;
static size_t a_cache_cap  = 0;

/* ---- required function ---- */
seq_t a(idx_t n)
{
    /* generate terms up to the requested index */
    while (a_cache_len <= (size_t)n) {
        /* select the stream with the smaller next b */
        size_t choice = (stream[0].next_b <= stream[1].next_b) ? 0 : 1;

        seq_t b   = stream[choice].next_b;
        seq_t tri = b * (b + 1) / 2;     /* T(b) */
        seq_t val = tri * tri;           /* a(n) = T(b)^2 */

        /* store the new term */
        if (a_cache_len >= a_cache_cap)
            grow_seq_arr(&a_cache, &a_cache_cap, a_cache_len + 4);
        a_cache[a_cache_len++] = val;

        /* advance the chosen stream */
        seq_t m_next = stream[choice].m * 3 + stream[choice].k * 8;
        seq_t k_next = stream[choice].m + stream[choice].k * 3;
        stream[choice].m      = m_next;
        stream[choice].k      = k_next;
        stream[choice].next_b = (m_next - 1) / 2;
    }

    return a_cache[(size_t)n];
}
